\set ON_ERROR_STOP on

-- Values are generated by the disposable runner and never stored in this fixture.
WITH person AS (
  INSERT INTO public.people (first_name, identification, email, updated_at)
  VALUES ('Auth Active', '9-1000-0001', 'auth-active@example.test', now())
  RETURNING id
)
INSERT INTO public.users (full_name, identification, email, password_hash, person_id, updated_at)
SELECT 'Auth Active', '9-1000-0001', 'auth-active@example.test', :'auth_login_password_hash', id, now()
FROM person;

